package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.io.*;
import java.net.URI;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Asynchronous submit/callback transport. Authentication always uses the exact received bytes. */
public final class HttpAgentAdapter implements AgentAdapter {
  public static final String KEY_ID="x-agentweave-key-id",TIMESTAMP="x-agentweave-timestamp",DELIVERY_ID="x-agentweave-delivery-id",SIGNATURE="x-agentweave-signature";
  private record Replay(boolean completed,long expiresAt){}
  private static final class Active {volatile CompletableFuture<?> future;volatile InputStream body;volatile boolean timedOut;void abort(){if(future!=null)future.cancel(true);if(body!=null)try{body.close();}catch(IOException ignored){}}}
  private final AgentTransportConfig config;private final HttpClient client;private volatile Handlers handlers;
  private final Map<String,Replay> replay=new LinkedHashMap<>();private final Set<Active> active=ConcurrentHashMap.newKeySet();
  private ScheduledExecutorService timers;
  public HttpAgentAdapter(AgentTransportConfig config){this(config,HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NORMAL).build());}
  public HttpAgentAdapter(AgentTransportConfig config,HttpClient client){this.config=config;this.client=client;}
  public String kind(){return "http";}
  public synchronized void start(Handlers handlers){if(this.handlers!=null){if(this.handlers==handlers)return;throw new AdapterError("ADAPTER_START_FAILED",false,"HTTP adapter already has handlers");}this.handlers=Objects.requireNonNull(handlers);timers=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"tenvyr-http-adapter");t.setDaemon(true);return t;});timers.scheduleAtFixedRate(()->cleanup(System.currentTimeMillis()),config.replayTtlMs,config.replayTtlMs,TimeUnit.MILLISECONDS);}
  public ObjectNode invoke(ObjectNode value,ObjectNode pinned)throws Exception{if(handlers==null)throw new AdapterError("ADAPTER_NOT_STARTED",true,"HTTP adapter is not started");ObjectNode invocation=Protocol.invocation(value);String agent=invocation.path("target").path("agent").asText();AgentTransportConfig.HttpProfile live=config.httpForAgent(agent);if(live==null)throw new AdapterError(pinned==null?"HTTP_AGENT_NOT_CONFIGURED":"EXECUTOR_PROFILE_MISMATCH",false,"HTTP agent profile is unavailable");if(pinned!=null&&!pinned.has("httpProfile"))throw new AdapterError("EXECUTOR_PROFILE_MISMATCH",false,"Pinned executor is missing HTTP profile");String submit=pinned==null?live.submitUrl():pinned.path("httpProfile").path("submitUrl").asText();int timeout=pinned==null?live.requestTimeoutMs():pinned.path("httpProfile").path("requestTimeoutMs").asInt(),limit=pinned==null?live.maxResponseBytes():pinned.path("httpProfile").path("maxResponseBytes").asInt();ObjectNode request=Protocol.httpRequest(Json.object("schemaVersion","1","invocation",invocation,"resultDelivery",Json.object("mode","callback","callbackUrl",config.callbackUrlFor(agent),"authentication",Json.object("scheme","hmac-sha256","keyId",live.keyId()))));
    HttpRequest.Builder builder=HttpRequest.newBuilder(URI.create(submit)).timeout(Duration.ofMillis(timeout)).header("Content-Type","application/json").header("Accept","application/json").header("Idempotency-Key",invocation.path("invocationId").asText()).header("User-Agent","Tenvyr-Orchestrator/0.1.0").POST(HttpRequest.BodyPublishers.ofString(Json.stringify(request)));if(live.bearer()!=null)builder.header("Authorization","Bearer "+live.bearer());String traceparent=traceparent(invocation);if(traceparent!=null)builder.header("traceparent",traceparent);
    Active operation=new Active();active.add(operation);ScheduledFuture<?> alarm=timers.schedule(()->{operation.timedOut=true;operation.abort();},timeout,TimeUnit.MILLISECONDS);
    try {CompletableFuture<HttpResponse<InputStream>> future=client.sendAsync(builder.build(),HttpResponse.BodyHandlers.ofInputStream());operation.future=future;HttpResponse<InputStream> response=future.get(timeout,TimeUnit.MILLISECONDS);operation.body=response.body();int status=response.statusCode();if(status!=202)throw new AdapterError("HTTP_REJECTED",status==408||status==429||status>=500,"Remote HTTP agent rejected invocation",status,null);if(!response.headers().firstValue("content-type").orElse("").toLowerCase(Locale.ROOT).contains("application/json"))throw invalidResponse(null);
      long contentLength=response.headers().firstValueAsLong("content-length").orElse(-1);if(contentLength>limit)throw new AdapterError("HTTP_RESPONSE_TOO_LARGE",false,"Remote HTTP response exceeded limit");byte[] bytes=readBounded(operation.body,limit);if(operation.timedOut)throw new AdapterError("HTTP_REQUEST_TIMEOUT",true,"HTTP agent request timed out");ObjectNode accepted;try{accepted=Protocol.httpAccepted(Json.parse(new String(bytes,StandardCharsets.UTF_8)));}catch(Exception error){throw invalidResponse(error);}if(!accepted.path("invocationId").asText().equals(invocation.path("invocationId").asText()))throw new AdapterError("HTTP_INVOCATION_MISMATCH",false,"Remote HTTP acceptance did not match invocation");return Json.object("adapter","http","invocationId",invocation.path("invocationId"),"dispatchedAt",Protocol.jsInstant(Instant.now()),"dispatchId",accepted.path("runId"));
    }catch(AdapterError error){throw error;}catch(Exception error){throw new AdapterError(operation.timedOut||error instanceof TimeoutException?"HTTP_REQUEST_TIMEOUT":"HTTP_CONNECTION_FAILED",true,"HTTP agent request failed",0,error);}finally{alarm.cancel(false);operation.abort();active.remove(operation);}
  }
  private byte[] readBounded(InputStream input,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream(Math.min(max,8192));byte[] buffer=new byte[8192];int total=0,count;while((count=input.read(buffer))!=-1){total+=count;if(total>max)throw new AdapterError("HTTP_RESPONSE_TOO_LARGE",false,"Remote HTTP response exceeded limit");out.write(buffer,0,count);}return out.toByteArray();}
  private AdapterError invalidResponse(Throwable error){return new AdapterError("HTTP_INVALID_RESPONSE",false,"Remote HTTP agent returned an invalid response",0,error);}
  public String handleCallback(String agent,String keyId,String timestamp,String deliveryId,String signature,byte[] rawBody,String remoteAddress,Long nowOverride)throws Exception {AgentTransportConfig.HttpProfile profile=config.httpForAgent(agent);if(profile==null||keyId==null||!keyId.equals(profile.keyId()))throw unauthorized();long now=nowOverride==null?System.currentTimeMillis():nowOverride;verify(profile.secret(),timestamp,deliveryId,signature,rawBody,config.callbackMaxSkewSeconds,now);if(deliveryId.length()>255)throw new AdapterError("CALLBACK_INVALID",false,"Callback delivery id exceeds durable bound");Handlers current=handlers;if(current==null)throw new AdapterError("CALLBACK_HANDLER_UNAVAILABLE",true,"Callback handlers unavailable");String replayKey=agent+'\0'+keyId+'\0'+deliveryId;
    synchronized(replay){cleanupLocked(now);Replay entry=replay.get(replayKey);if(entry!=null&&entry.completed)return "duplicate";if(entry==null){if(replay.size()>=config.replayMaxEntries){Iterator<String> keys=replay.keySet().iterator();if(keys.hasNext()){keys.next();keys.remove();}}replay.put(replayKey,new Replay(false,now+config.replayTtlMs));}}
    try{ObjectNode value;try{value=Json.requireObject(Json.parse(new String(rawBody,StandardCharsets.UTF_8)),"Callback");}catch(Exception error){throw new AdapterError("CALLBACK_INVALID",false,"HTTP callback body is invalid JSON",0,error);}boolean resultShape=value.path("status").isTextual()&&value.path("completedAt").isTextual(),eventShape=value.path("eventId").isTextual()&&value.path("sequence").isNumber()&&value.path("type").isTextual();if(resultShape&&eventShape)throw new AdapterError("CALLBACK_AMBIGUOUS",false,"Callback body matches result and event");ObjectNode transport=Json.object("adapter","http","receivedAt",Protocol.jsInstant(Instant.now()),"deliveryId",deliveryId,"keyId",keyId,"remoteAddress",remoteAddress);if(eventShape){ObjectNode event=Protocol.event(value);try{current.event(event,transport);}catch(Exception e){throw new AdapterError("EVENT_HANDLER_FAILED",!(e instanceof AgentEventService.PayloadTooLarge),"HTTP callback event handler failed",0,e);}}else{ObjectNode result=Protocol.result(value);current.result(result,transport);}synchronized(replay){replay.put(replayKey,new Replay(true,now+config.replayTtlMs));}return "processed";
    }catch(Exception error){synchronized(replay){replay.remove(replayKey);}throw error;}
  }
  public int callbackStatus(Throwable error){if(error instanceof Protocol.ValidationError||error instanceof IllegalArgumentException)return 400;if(error instanceof AdapterError e)return switch(e.code){case "CALLBACK_UNAUTHORIZED"->401;case "CALLBACK_INVALID","CALLBACK_AMBIGUOUS"->400;case "CALLBACK_HANDLER_UNAVAILABLE"->503;case "EVENT_HANDLER_FAILED"->e.retryable?503:400;default->500;};return 500;}
  public static String signature(String secret,String timestamp,String deliveryId,byte[] rawBody){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));mac.update((timestamp+"."+deliveryId+".").getBytes(StandardCharsets.UTF_8));return "v1="+HexFormat.of().formatHex(mac.doFinal(rawBody));}catch(Exception e){throw new IllegalStateException(e);}}
  public static void verify(String secret,String timestamp,String deliveryId,String signature,byte[] body,int maxSkew,long nowMs){if(timestamp==null||!timestamp.matches("[0-9]+")||deliveryId==null||deliveryId.isEmpty()||signature==null||!signature.matches("v1=[a-f0-9]{64}"))throw unauthorized();double seconds;try{seconds=Double.parseDouble(timestamp);}catch(Exception e){throw unauthorized();}if(!Double.isFinite(seconds)||Math.abs(Math.floor(nowMs/1000.0)-seconds)>maxSkew)throw unauthorized();byte[] actual=signature.getBytes(StandardCharsets.US_ASCII),expected=signature(secret,timestamp,deliveryId,body).getBytes(StandardCharsets.US_ASCII);if(!MessageDigest.isEqual(actual,expected))throw unauthorized();}
  private static AdapterError unauthorized(){return new AdapterError("CALLBACK_UNAUTHORIZED",false,"HTTP callback authentication failed");}
  public static String traceparent(ObjectNode invocation){String trace=Json.text(invocation.path("trace"),"traceId"),id=Json.text(invocation,"invocationId");if(trace==null||id==null)return null;trace=trace.replace("-","").toLowerCase(Locale.ROOT);if(!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))return null;return "00-"+trace+"-"+Json.sha256(id).substring(0,16)+"-01";}
  private void cleanup(long now){synchronized(replay){cleanupLocked(now);}} private void cleanupLocked(long now){replay.entrySet().removeIf(e->e.getValue().expiresAt<=now);}
  public synchronized void close(){handlers=null;if(timers!=null)timers.shutdownNow();timers=null;synchronized(replay){replay.clear();}for(Active operation:active)operation.abort();active.clear();}
}
